INSERT INTO _fleet_sync_status_state(machine_id,owner_route,head,floor,created_at,updated_at) VALUES(?2,?1 -> '$.ownerRoute',CAST(json_extract(?1,'$.head') AS INTEGER),CAST(json_extract(?1,'$.floor') AS INTEGER),CAST(?3 AS INTEGER),CAST(?4 AS INTEGER)) ON CONFLICT(machine_id) DO UPDATE SET owner_route=excluded.owner_route,head=excluded.head,floor=excluded.floor,updated_at=excluded.updated_at;
